dimensions.childDraw:
function (c, x, y, look, anim = {}) {
  if (!Smell1151.drawing) return previous.call(this, c, x, y, look, anim);
  const cv = Smell1151.pose({ ...look, short: true }, Smell1151.face({ x, y })); x = Math.round(x); y = Math.round(y);
  c.drawImage(cv, 0, 0, 24, 21, x - 12, y - 29, 24, 21);
  c.drawImage(cv, 0, 21, 24, 15, x - 12, y - 8, 24, 8);
}

